//! Differential test: the full DE-9IM matrix against GEOS (via shapely) on 1200 random pairs of
//! points, line strings and polygons with holes, on an integer grid so that vertex contacts,
//! shared edges and collinear overlaps are common. The reference matrices are in
//! `tests/fixtures/geos_de9im.csv`, generated by `fixtures/generate_de9im_pairs.py`.

#![cfg(feature = "alloc")]

use std::path::PathBuf;

use tpt_gis_geom::de9im::relate;
use tpt_gis_geom::multi::GeometryRef;
use tpt_gis_geom::{LineString, Point, Polygon};

fn parse_points(text: &str) -> Vec<Point> {
    text.split_whitespace()
        .map(|pair| {
            let (x, y) = pair.split_once(',').unwrap();
            Point::new(x.parse().unwrap(), y.parse().unwrap())
        })
        .collect()
}

/// A ring as a closed point list, since the polygon primitive expects closed rings.
fn closed(mut ring: Vec<Point>) -> Vec<Point> {
    if ring.first() != ring.last() {
        let first = ring[0];
        ring.push(first);
    }
    ring
}

/// Owned storage for one parsed geometry. The borrowed `GeometryRef` is built from it with
/// [`Owned::geometry`], passing the hole slices from [`Owned::holes`] so that they outlive it.
struct Owned {
    kind: char,
    points: Vec<Point>,
    rings: Vec<Vec<Point>>,
}

impl Owned {
    fn parse(kind: &str, coords: &str) -> Self {
        let kind = kind.chars().next().unwrap();
        if kind == 'A' {
            let rings = coords.split('|').map(|part| closed(parse_points(part))).collect();
            Owned { kind, points: Vec::new(), rings }
        } else {
            Owned { kind, points: parse_points(coords), rings: Vec::new() }
        }
    }

    /// The hole rings of a polygon (every ring after the exterior).
    fn holes(&self) -> Vec<&[Point]> {
        self.rings.iter().skip(1).map(Vec::as_slice).collect()
    }

    fn geometry<'b>(&'b self, holes: &'b [&'b [Point]]) -> GeometryRef<'b> {
        match self.kind {
            'P' => GeometryRef::Point(self.points[0]),
            'L' => GeometryRef::LineString(LineString::new(&self.points)),
            _ => GeometryRef::Polygon(Polygon::new(&self.rings[0], holes)),
        }
    }
}

#[test]
fn de9im_matrices_agree_with_geos() {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/geos_de9im.csv");
    let text = std::fs::read_to_string(path).unwrap();
    let mut checked = 0;
    let mut mismatches = Vec::new();
    for (index, row) in text.lines().enumerate() {
        if row.starts_with('#') || row.trim().is_empty() {
            continue;
        }
        let f: Vec<&str> = row.split(';').collect();
        let a = Owned::parse(f[0], f[1]);
        let b = Owned::parse(f[2], f[3]);
        let (holes_a, holes_b) = (a.holes(), b.holes());
        let want = f[4];
        let got = relate(&a.geometry(&holes_a), &b.geometry(&holes_b))
            .expect("supported geometry")
            .to_string();
        if got != want {
            mismatches.push(format!("row {}: {row} -> ours {got}, GEOS {want}", index + 1));
        }
        checked += 1;
    }
    assert!(checked >= 1000, "checked {checked} rows");
    assert!(
        mismatches.is_empty(),
        "{} of {checked} differ:\n{}",
        mismatches.len(),
        mismatches.join("\n")
    );
}
